                        return withUnsafeTemporaryAllocation(of: SIMD<UInt8>.self, capacity: 1) {
                            result in
                            unsafe portLookup8U8InVectorCode(
                                result.baseAddress.unsafelyUnwrapped,
                                at: &indices,
